"""Show panel and actual UV-textured artwork comparisons independently."""
import argparse,json
from pathlib import Path


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('out',type=Path);a=ap.parse_args();out=a.out.resolve();views={}
    for name,pattern in [('Base · oblique','whole-{}-e15-a60'),('Base · rear','whole-{}-e15-a180'),('Base · top','whole-{}-top'),('Base · underside','whole-{}-bottom'),('Crossbar · oblique','member-4268930-{}-oblique'),('Crossbar · underside','member-4268930-{}-bottom'),('Housing · oblique','member-4527988-{}-oblique'),('Artwork · straight on','logo-{}-normal'),('Artwork · oblique','logo-{}-oblique')]:views[name]={stage:str(out/(pattern.format(stage)+'.png')) for stage in ['before','panels','texture']}
    html='''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;font-family:var(--font-sans),sans-serif;color:var(--foreground)}h2{font-size:22px;margin:0 0 14px}.stats{display:flex;flex-wrap:wrap;gap:25px}.stats strong{display:block;font-size:24px}.stats span,p{font-size:13px;color:var(--muted-foreground)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button,select{font:inherit;font-size:13px;padding:8px 11px;background:var(--card);color:var(--foreground);border:1px solid var(--border);border-radius:6px}.active{background:var(--primary);color:var(--primary-foreground)}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pair img{width:100%;border-radius:6px}.label{font-size:12px;margin-bottom:6px}p{line-height:1.55}.note{padding:16px;border-radius:8px;background:var(--muted);margin-top:12px}.note p{margin:0}.last{margin-bottom:0}</style></head><body><h2>Crossbar panels → textured source artwork</h2><div class="stats"><div><strong id="count">66,502</strong><span id="delta">1,578 triangles saved · 2.32%</span></div><div><strong>9,869</strong><span>crossbar · previously 10,494</span></div><div><strong>11 KB</strong><span>embedded artwork PNG</span></div></div><nav><button id="panels">Panel only</button><button id="texture" class="active">Panel + texture</button><select id="view" aria-label="Comparison view"></select></nav><div class="pair"><div><div class="label">Previous · 68,080 triangles</div><img id="before" alt="Previous Base geometry and artwork"></div><div><div class="label" id="label">Candidate · 66,502 triangles</div><img id="candidate" alt="Candidate Base with actual texture UVs"></div></div><div class="note"><p><b>Artwork is now a real textured primitive.</b> The source’s coplanar logo/lettering becomes an embedded sRGB colour texture with UVs and an edge gutter. The finite patch saves 953 housing triangles. Choose an artwork close-up to inspect it.</p></div><p><b>Grooves retained:</b> that trial reached a 6 mm backing and had uncovered openings. It was rejected. Three less useful panel alternatives are also excluded.</p><p class="last">All 2,822 light triangles and 338 other members retain exact rendered attributes. LED masks match in all 18 diagnostic views; maximum silhouette-mask difference is 0.0374%. Collision and installed assets stay unchanged. These renders read the exported GLB’s UVs and PNG; they are fixed-pose diagnostics, not runtime PBR or mip testing.</p><script>const views=DATA;let stage='texture';const select=document.getElementById('view');for(const k of Object.keys(views))select.add(new Option(k,k));function update(){document.getElementById('before').src=views[select.value].before;document.getElementById('candidate').src=views[select.value][stage];document.getElementById('count').textContent=stage==='texture'?'66,502':'67,455';document.getElementById('delta').textContent=stage==='texture'?'1,578 triangles saved · 2.32%':'625 triangles saved · 0.92%';document.getElementById('label').textContent=stage==='texture'?'Candidate · 66,502 triangles':'Candidate · 67,455 triangles';for(const k of ['panels','texture'])document.getElementById(k).classList.toggle('active',stage===k);}select.onchange=update;for(const k of ['panels','texture'])document.getElementById(k).onclick=()=>{stage=k;update();};update();</script></body></html>'''.replace('DATA',json.dumps(views));(out/'review.html').write_text(html);print(out/'review.html')
if __name__=='__main__':main()
